const incoming = $input.first().json;
const body = incoming.body ?? incoming;
const now = new Date();
const randomSuffix = Math.random().toString(36).slice(2, 8).toUpperCase();

const candidateId = String(body.candidate_id || body.linkedin_application_id || `CAND-${randomSuffix}`);
const jobId = String(body.job_id || 'JOB-001');
const promptVersion = String(body.prompt_version || 'screening-v1.0');

return [{
  json: {
    ...body,
    source: body.source || 'linkedin_jobs',
    candidate_id: candidateId,
    job_id: jobId,
    resume_text: String(body.resume_text || ''),
    screening_answers: Array.isArray(body.screening_answers) ? body.screening_answers : [],
    recruiter_notes: String(body.recruiter_notes || ''),
    conversation_notes: String(body.conversation_notes || ''),
    prompt_version: promptVersion,
    trace_id: `TRC-${now.toISOString().slice(0, 10).replace(/-/g, '')}-${randomSuffix}`,
    idempotency_key: `APP-${candidateId}-${jobId}-${promptVersion}`,
    received_at: now.toISOString()
  }
}];
